using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ANM.LogVisualizacionAnuncios;namespace GraphApi.Services.ANM.LogVisualizacionAnuncios{    public class LogVisualizacionAnunciosService : ILogVisualizacionAnunciosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public LogVisualizacionAnunciosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadLogVisualizacionAnuncios>> GetLogVisualizacionAnuncios(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM anm.LogVisualizacionAnuncios (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadLogVisualizacionAnuncios>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetLogVisualizacionAnunciosDynamic(            int? logVisualizacionAnuncioID,            int? anuncioID,            int? usuarioID,            string? medio,            string? iPOrigen,            string? userAgent,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "LogVisualizacionAnuncioID, AnuncioID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM anm.LogVisualizacionAnuncios (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (logVisualizacionAnuncioID.HasValue)            {                vSql.Append(" AND LogVisualizacionAnuncioID = @LogVisualizacionAnuncioID");                vParameters.Add("LogVisualizacionAnuncioID",logVisualizacionAnuncioID);            }            if (!string.IsNullOrWhiteSpace(medio))            {                vSql.Append(" AND Medio LIKE @Medio");                vParameters.Add("Medio",$"%{medio}%");            }            if (!string.IsNullOrWhiteSpace(iPOrigen))            {                vSql.Append(" AND IPOrigen LIKE @IPOrigen");                vParameters.Add("IPOrigen",$"%{iPOrigen}%");            }            if (!string.IsNullOrWhiteSpace(userAgent))            {                vSql.Append(" AND UserAgent LIKE @UserAgent");                vParameters.Add("UserAgent",$"%{userAgent}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadLogVisualizacionAnuncios> CreateLogVisualizacionAnuncios(clCreateLogVisualizacionAnuncios objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO anm.LogVisualizacionAnuncios                (AnuncioID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@AnuncioID, @UsuarioID, @Medio, @IPOrigen, @UserAgent, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.AnuncioID,                objInput.UsuarioID,                objInput.Medio,                objInput.IPOrigen,                objInput.UserAgent,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT LogVisualizacionAnuncioID, AnuncioID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado                FROM anm.LogVisualizacionAnuncios (NOLOCK)                WHERE LogVisualizacionAnuncioID = @LogVisualizacionAnuncioID;";            var vReadParams = new { LogVisualizacionAnuncioID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadLogVisualizacionAnuncios>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el LogVisualizacionAnuncio con ID {vNewId}.");            return vCreated;        }        public async Task<clReadLogVisualizacionAnuncios?> UpdateLogVisualizacionAnuncios(clUpdateLogVisualizacionAnuncios objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("LogVisualizacionAnuncioID", objInput.LogVisualizacionAnuncioID);            if (objInput.AnuncioID != null)            {                vSets.Add("AnuncioID = @AnuncioID");                vParameters.Add("AnuncioID", objInput.AnuncioID);            }            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.Medio is not null)            {                vSets.Add("Medio = @Medio");                vParameters.Add("Medio", objInput.Medio);            }            if (objInput.IPOrigen is not null)            {                vSets.Add("IPOrigen = @IPOrigen");                vParameters.Add("IPOrigen", objInput.IPOrigen);            }            if (objInput.UserAgent is not null)            {                vSets.Add("UserAgent = @UserAgent");                vParameters.Add("UserAgent", objInput.UserAgent);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE anm.LogVisualizacionAnuncios                SET {vSetClause}                WHERE LogVisualizacionAnuncioID = @LogVisualizacionAnuncioID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT LogVisualizacionAnuncioID, AnuncioID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado                FROM anm.LogVisualizacionAnuncios (NOLOCK)                WHERE LogVisualizacionAnuncioID = @LogVisualizacionAnuncioID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadLogVisualizacionAnuncios>(sSelect, new {  objInput.LogVisualizacionAnuncioID });        }        public async Task<bool> DeleteLogVisualizacionAnuncios(int nLogVisualizacionAnunciosID)        {            const string sSql = @"                DELETE FROM anm.LogVisualizacionAnuncios                WHERE LogVisualizacionAnuncioID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nLogVisualizacionAnunciosID });            return vAffected > 0;        }    }}